<template>
  <div class="confirm-wrapper" v-if="orderInfo">
    <div class="page-scroll">
      <div class="remark" @click="handleRemark('open')">
        <span class="left">订单备注</span>
        <div class="right">
          <span class="desc" v-show="!remark">点击添加订单备注</span>
          <span v-show="remark">{{remark}}</span>
          <i class="icon iconfont">&#xe603;</i>
        </div>
      </div>
      <div class="leader-box">
        <div class="name-box">
          <span class="tag main-color-bg">团长</span>
          <span>{{orderInfo.leader_info.name}}</span>
          <span class="desc">{{orderInfo.leader_info.pick_address.name}}</span>
        </div>
        <div class="phone-box" v-if="orderInfo.leader_info.phone">
          <i class="icon iconfont">&#xe6dd;</i>
          <span>联系电话：{{orderInfo.leader_info.phone}}</span>
        </div>
        <div>
          <i class="icon iconfont">&#xe60b;</i>
          <span>取货地址：{{orderInfo.leader_info.pick_address.pick_addr}}</span>
        </div>
      </div>
      <div class="goods-box">
        <div class="list">
          <div class="item" v-for="(item, index) in orderInfo.order.order_detail" :key="index">
            <div class="img-box">
              <img :src="item.image" alt="">
            </div>
            <div class="desc-box">
              <div class="name">{{item.name}}</div>
              <div class="total-buy">取货时间：{{orderInfo.leader_info.start_time + ' - ' + orderInfo.leader_info.end_time}}</div>
              <div class="arrive-time">
                <span>{{item.arrive_title}}</span>
              </div>
              <div class="price-box">
                <div>
                  <span class="tag" v-show="item.is_level == 1">VIP</span>
                  <span class="now now-icon main-color-font">¥</span>
                  <span class="now main-color-font">{{item.is_level == 1 ? item.discount_price : item.price }}</span>
                  <span class="old">¥{{item.is_level == 1 ? item.price : item.old_price  }}</span>
                </div>
                <div>×{{item.num}}</div>
              </div>
            </div>
          </div>
        </div>
        <div class="coupon-box" @click="selectCoupon">
          <div class="left">平台优惠券</div>
          <div class="right">
            <span class="txt">{{orderInfo.system_coupon.name}}</span>
            <i class="icon iconfont">&#xe603;</i>
          </div>
        </div>
        <div class="score-box" v-if="orderInfo.score.score_can_use_count != 0">
          <div>本单可使用积分<span class="red">{{orderInfo.score.score_can_use_count}}个</span>，可抵扣金额<span class="red">¥{{orderInfo.score.score_deducte}}</span></div>
          <div>
            <mt-switch v-model="selectScore" @change="switchScore"></mt-switch>
          </div>
        </div>
      </div>
    </div>
    <div class="footer">
      <div class="price-box">
        <span class="item main-color-font">待支付：¥<i class="price">{{orderInfo.order.actual_total_money}}</i></span>
        <span class="item gray">已优惠：¥<i class="price">{{orderInfo.order.actual_discount_money}}</i></span>
      </div>
      <div class="btn main-color-bg" @click="goPay">去支付</div>
    </div>
    <div class="remark-mask" v-show="showMask" @click="handleRemark('close')">
      <div class="remark-content" @click.stop="handleRemark('none')">
        <div class="title">添加备注</div>
        <div class="input-box">
          <textarea name="remark" placeholder="请输入备注" v-model="inputTxt"></textarea>
        </div>
        <div class="btn-box">
          <span class="btn" @click="handleRemark('close')">取消</span>
          <span class="btn confirm main-color-font" @click="handleRemark('confirm')">确定</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'Confirm',
  data () {
    return {
      selectScore: true,
      remark: '',
      showMask: false,
      inputTxt: '',
      leader_id: '',
      order_id: '',
      orderInfo: ''
    }
  },
  created () {
    this.leader_id = this.$util.storage.get('leader_id')
    this.order_id = this.$global.orderId
    this.getOrderInfo()
  },
  methods: {
    selectCoupon () {
      let couponId = this.orderInfo.system_coupon.id ? this.orderInfo.system_coupon.id : 0
      this.$router.push({ path: '/coupon', query: { couponId: couponId, orderId: this.order_id } })
    },
    // 选择积分
    switchScore () {
      if (this.selectScore) {
        this.orderInfo.order.actual_total_money = this.orderInfo.order.actual_total_money * 1 - this.orderInfo.score.score_deducte * 1
      } else {
        this.orderInfo.order.actual_total_money = this.orderInfo.order.actual_total_money * 1 + this.orderInfo.score.score_deducte * 1
      }
    },
    // 跳转链接
    goUrl (param) {
      console.log('3333333', param)
    },
    // 是否显示备注弹窗
    handleRemark (status) {
      if (status == 'open') {
        this.inputTxt = this.remark
        this.showMask = true
        return
      }
      if (status == 'none') {
        return false
      }
      if (status == 'close') {
        this.showMask = false
        return
      }
      if (status == 'confirm') {
        this.remark = this.inputTxt
        this.showMask = false
      }
    },
    // 获取支付ID
    async goPay () {
      let param = {
        leader_id: this.leader_id,
        order_id: this.order_id,
        use_score: this.selectScore ? 1 : 0,
        note: this.remark
      }
      let res = await this.$api.getPayId(param)
      if (!res || !res.order_id) return
      if (this.$util.checkWeixinApp()) {
        this.$wx.miniProgram.navigateTo({
          url: `/pages/pay/index?order_id=${res.order_id}&type=plat`
        })
      } else {
        location.replace(process.env.VUE_APP_BASE_API + '/wap.php?g=Wap&c=Pay&a=check&type=plat&order_id=' + res.order_id + '&ticket=' + this.$util.storage.get('ticket') + '&device_id=packapp')
      }
    },
    // 获取订单详情
    async getOrderInfo () {
      let param = {
        leader_id: this.leader_id,
        order_id: this.order_id
      }
      if (this.$global.couponId > 0) {
        param.unsys_coupon = 0
        param.sysc_id = this.$global.couponId
      } else if (this.$global.couponId === 0) {
        param.unsys_coupon = 1
      }
      this.$global.couponId = ''
      let res = await this.$api.getOrderInfo(param)
      if (!res) return
      this.orderInfo = res
    }
  }
}
</script>

