      margin-bottom 15px
      .left
        flex-shrink 0
        padding-right 10px
      .right
        flexbox()
        align-items center
        word-break break-all
        .desc
          color #999
        .icon
          flex-shrink 0
          color #bbb
          font-size 12px
          padding-left 5px
    .leader-box
      background #fff
