          font-size 12px
          margin-left 10px
      .phone-box
        margin-bottom 15px
      .icon
        color #7ab900
        padding-right 5px
    .goods-box
      background #fff
      margin-bottom 40px
      .list
        .item
          flexbox()
          padding 15px
          border-bottom 1PX solid #efefef
          .img-box
            width 80px
