        .red
          color red
          padding 0 5px
        .mint-switch-input:checked + .mint-switch-core
          border-color #fe3112
          background-color #fe3112
  .footer
    background #fff
    height 45px
    flexbox()
    align-items center
    box-shadow -2px 0 5px #ddd
    border-top 1PX solid #f2f2f2
    .price-box
      flex-grow 1
      flexbox()
      align-items center
