      font-size 14px
      .item
        color $color-main
        .price
          font-size 18px
          font-style normal
          font-weight bold
        &.gray
          color #999
          margin-left 10px
          padding-left 10px
          border-left 1PX solid #ddd
    .btn
      height 100%
      line-height 45px
      background $color-main
      color #fff
      padding 0 20px
      font-size 16px
  .remark-mask
    position absolute
    top 0
